// parse.rs — SKU line parser
pub fn parse_sku(line: &str) -> Option<(&str, u32)> {
    let mut parts = line.split_whitespace();
    let sku = parts.next()?;
    let qty = parts.next()?.parse().ok()?;
    Some((sku, qty))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(parse_sku("DESK-RS-01 2"), Some(("DESK-RS-01", 2)));
    }
}

